function riskFlags(best, platform, region, edition, prefs) {
  const flags = [];
  if (!best.channel.physical && prefs.wantsCancel) {
    flags.push({
      title: "Tu ventana de reembolso se cierra en la precarga, no en el lanzamiento",
      body: `En ${platform.label}, una reserva digital deja de ser reembolsable en el momento en que empieza la descarga, unos ${platform.preloadLeadDays} día${platform.preloadLeadDays === 1 ? "" : "s"} antes del lanzamiento. Si conservar la opción de echarte atrás importa más que jugar en el desbloqueo, no inicies la precarga.`,
      severity: "high"
    });
  }
  if (best.channel.id === "retailer-code" && prefs.wantsPreload) {
    flags.push({
      title: "Un código tardío puede costarte la precarga",
      body: "Los códigos digitales de minorista suelen entregarse 24 a 72 horas antes del lanzamiento. Eso cae dentro de la ventana de precarga en Xbox y puede ir justo en PlayStation, así que quizá estés descargando el día del lanzamiento.",
      severity: "medium"
    });
  }
  if (best.channel.physical) {
    flags.push({
      title: "Los discos también descargan un parche del primer día",
      body: "Un disco elimina la descarga base pero no el parche del lanzamiento. Calcula el ancho de banda de todos modos y espera instalar un rato antes de jugar.",
      severity: "medium"
    });
  }
  if (best.channel.id === "marketplace-key") {
    flags.push({
      title: "Las claves del mercado gris conllevan riesgo de revocación",
      body: "Una clave revocada normalmente significa sin juego y sin reembolso, y el soporte del editor no intervendrá en un derecho que no vendió. El ahorro rara vez vale la exposición en un título de lanzamiento.",
      severity: "high"
    });
  }
  if (edition.id !== "standard") {
    flags.push({
      title: `Las bonificaciones de ${edition.label} se vinculan a la cuenta compradora`,
      body: `${edition.note} Cambiar de canal o plataforma después de pedir significa volver a comprar el paquete de bonificaciones, así que decide la plataforma antes que la edición.`,
      severity: "low"
    });
  }
  if (region.consumerLaw >= 8 && !best.channel.physical) {
    flags.push({
      title: "Tienes un derecho legal de cancelación, úsalo antes de descargar",
      body: `${region.note} Ese derecho normalmente sobrevive solo mientras el contenido digital no se ha descargado, que es el mismo límite que aplica la tienda.`,
      severity: "low"
    });
  }
  return flags;
}
export function rankChannels(input) {
  const platform = platformById(input.platform) ?? PLATFORMS[0];
  const region = regionById(input.region) ?? REGIONS[0];
  const edition = editionById(input.edition) ?? EDITIONS[0];
  const prefs = input.prefs;
  const weights = weightsFor(prefs);
  const ranked = CHANNELS.filter((c) => c.platforms.includes(platform.id)).map((channel) => {
    const adj = adjustedAxes(channel, platform, region, edition);
    const axes = Object.keys(AXIS_LABELS).map((id) => ({
      id,
      label: AXIS_LABELS[id],
      raw: adj[id],
      weight: weights[id],
      detail: AXIS_DETAIL[id]
    }));
    const score = Math.round(axes.reduce((sum, a) => sum + a.raw / 10 * a.weight, 0) * 10) / 10;
    const sorted = [...axes].sort((a, b) => b.raw - a.raw);
    return {
      channel,
      score,
      axes,
      strengths: sorted.slice(0, 2).filter((a) => a.raw >= 6).map((a) => a.label),
      risks: sorted.slice(-2).filter((a) => a.raw <= 4).map((a) => a.label),
      confidence: channel.confidence
    };
  }).sort((a, b) => b.score - a.score || a.channel.label.localeCompare(b.channel.label));
  const best = ranked[0];
  const runnerUp = ranked[1];
  const wanted = [
    prefs.wantsPreload ? "jugar en el momento del desbloqueo" : null,
    prefs.wantsCancel ? "conservar la opción de cancelar" : null,
    prefs.wantsResale ? "valor de reventa o préstamo" : null
  ].filter(Boolean);
  const priorities = wanted.length === 0 ? "sin una preferencia fuerte más allá del valor" : wanted.length === 1 ? wanted[0] : `${wanted.slice(0, -1).join(", ")} y ${wanted.at(-1)}`;
  const headline = `${best.channel.short} en ${platform.label}`;
  const reason = `Porque nos dijiste que ${priorities} importa, ${best.channel.label.toLowerCase()} obtiene ${best.score} de 100 para un pedido de ${edition.label} en ${region.label}, liderando en ${best.strengths.join(" y ").toLowerCase() || "equilibrio general"}${runnerUp ? `, por delante de ${runnerUp.channel.short.toLowerCase()} con ${runnerUp.score}` : ""}.`;
  return {
    platform,
    region,
    edition,
    prefs,
    weights,
    ranked,
    best,
    runnerUp,
    headline,
    reason,
    riskFlags: riskFlags(best, platform, region, edition, prefs),
    timeline: timeline(platform, region)
  };
}
